import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const NhanTin = () => {
    const [tabActive, setTabActive] = useState('all');
    const [selectedRooms, setSelectedRooms] = useState([]);
    const [message, setMessage] = useState('');

    // Khởi tạo danh sách phòng
    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    // Hàm chọn/bỏ chọn phòng
    const toggleRoom = (roomId) => {
        if (selectedRooms.includes(roomId)) {
            setSelectedRooms(selectedRooms.filter(id => id !== roomId));
        } else {
            setSelectedRooms([...selectedRooms, roomId]);
        }
    };

    // Kiểm tra điều kiện gửi tin
    const canSendPrivate = selectedRooms.length > 0 && message.trim() !== '';

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden'
        }} className="glass-card">

            {/* Thanh Tab Chuyển đổi */}
            <div style={{ padding: '20px', display: 'flex', gap: '15px' }}>
                <button 
                    onClick={() => setTabActive('all')}
                    style={{
                        padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold',
                        backgroundColor: tabActive === 'all' ? '#333' : 'rgba(255,255,255,0.6)',
                        color: tabActive === 'all' ? '#fff' : '#333', cursor: 'pointer', transition: '0.3s'
                    }}
                >
                    Nhắn tin chung
                </button>
                <button 
                    onClick={() => setTabActive('private')}
                    style={{
                        padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold',
                        backgroundColor: tabActive === 'private' ? '#8b5e5e' : 'rgba(255,255,255,0.6)',
                        color: tabActive === 'private' ? '#fff' : '#333', cursor: 'pointer', transition: '0.3s'
                    }}
                >
                    Nhắn tin riêng
                </button>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', overflow: 'hidden' }}>
                {tabActive === 'all' ? (
                    /* GIAO DIỆN NHẮN TIN CHUNG */
                    <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
                        <div style={{ flex: 1, padding: '10px', overflowY: 'auto' }}>
                            <div style={{ display: 'flex', gap: '10px', alignItems: 'center', marginBottom: '15px' }}>
                                <div style={{ width: '35px', height: '35px', borderRadius: '50%', backgroundColor: '#333', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '10px', fontWeight: 'bold' }}>AD</div>
                                <div style={{ backgroundColor: 'rgba(255,255,255,0.9)', padding: '12px 18px', borderRadius: '18px 18px 18px 0', fontSize: '13px', color: '#333' }}>
                                    Hệ thống: Chào Admin, bạn có thể gửi tin nhắn đến toàn bộ cư dân tại đây.
                                </div>
                            </div>
                        </div>
                        <div style={{ display: 'flex', gap: '10px' }}>
                            <input 
                                style={{ flex: 1, padding: '15px', borderRadius: '15px', border: 'none', outline: 'none' }} 
                                placeholder="Nhập nội dung nhắn cho tất cả cư dân..." 
                            />
                            <button style={{ padding: '0 30px', borderRadius: '15px', border: 'none', backgroundColor: '#333', color: '#fff', fontWeight: 'bold', cursor: 'pointer' }}>Gửi</button>
                        </div>
                    </div>
                ) : (
                    /* GIAO DIỆN NHẮN TIN RIÊNG */
                    <div style={{ flex: 1, display: 'flex', gap: '20px' }}>

                        {/* Danh sách phòng bên trái */}
                        <div style={{ 
                            width: '230px', 
                            display: 'grid', 
                            gridTemplateColumns: 'repeat(5, 1fr)', 
                            gap: '6px', 
                            alignContent: 'flex-start', 
                            overflowY: 'auto',
                            paddingRight: '5px'
                        }}>
                            {allRooms.map(room => {
                                const isSelected = selectedRooms.includes(room);
                                return (
                                    <div 
                                        key={room} 
                                        onClick={() => toggleRoom(room)}
                                        style={{ 
                                            background: isSelected ? '#8b5e5e' : 'rgba(255,255,255,0.8)', 
                                            color: isSelected ? 'white' : '#333',
                                            padding: '8px 0', 
                                            borderRadius: '8px', 
                                            textAlign: 'center', 
                                            fontSize: '11px', 
                                            fontWeight: 'bold', 
                                            cursor: 'pointer',
                                            transition: '0.2s',
                                            border: isSelected ? 'none' : '1px solid rgba(255,255,255,0.3)'
                                        }}
                                    >
                                        {room}
                                    </div>
                                );
                            })}
                        </div>

                        {/* Khung nội dung bên phải */}
                        <div style={{ 
                            flex: 1, 
                            display: 'flex', 
                            flexDirection: 'column', 
                            backgroundColor: 'rgba(255,255,255,0.1)', 
                            borderRadius: '20px', 
                            border: '1px solid rgba(255,255,255,0.2)',
                            padding: '15px'
                        }}>
                            <div style={{ flex: 1, color: '#fff' }}>
                                <p style={{ fontSize: '14px', fontWeight: 'bold', marginBottom: '10px' }}>
                                    Gửi đến: {selectedRooms.length > 0 ? selectedRooms.join(', ') : 'Chưa chọn phòng'}
                                </p>
                                {selectedRooms.length === 0 && (
                                    <p style={{ opacity: 0.7, fontSize: '13px', fontStyle: 'italic' }}>Vui lòng chọn ít nhất một phòng bên trái để nhắn tin...</p>
                                )}
                            </div>

                            <div style={{ display: 'flex', gap: '10px' }}>
                                <input 
                                    style={{ flex: 1, padding: '15px', borderRadius: '15px', border: 'none', outline: 'none' }} 
                                    placeholder="Nhập nội dung nhắn riêng..." 
                                    value={message}
                                    onChange={(e) => setMessage(e.target.value)}
                                />
                                <button 
                                    disabled={!canSendPrivate}
                                    style={{ 
                                        padding: '0 25px', 
                                        borderRadius: '15px', 
                                        border: 'none', 
                                        backgroundColor: '#8b5e5e', 
                                        color: '#fff', 
                                        fontWeight: 'bold',
                                        opacity: canSendPrivate ? 1 : 0.5,
                                        cursor: canSendPrivate ? 'pointer' : 'not-allowed',
                                        transition: '0.3s'
                                    }}
                                >
                                    Gửi riêng
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default NhanTin;
